class BootstrapCompanyResponse{const BootstrapCompanyResponse({required this.groupId,required this.userId,required this.deviceId,required this.companyName,required this.ownerName});final String groupId,userId,deviceId,companyName,ownerName;factory BootstrapCompanyResponse.fromJson(Map<String,dynamic>j)=>BootstrapCompanyResponse(groupId:j['groupId'],userId:j['userId'],deviceId:j['deviceId'],companyName:j['companyName'],ownerName:j['ownerName']);}
