class AuthSession{const AuthSession({required this.groupId,required this.userId,required this.deviceId,required this.name,required this.profile,required this.isOwner,required this.accessToken,required this.accessTokenExpiresAt,required this.refreshToken,required this.refreshTokenExpiresAt,required this.offlineLeaseExpiresAt,required this.serverTimeUtc,required this.validatedAt});final String groupId,userId,deviceId,name,profile,accessToken,refreshToken;final bool isOwner;final DateTime accessTokenExpiresAt,refreshTokenExpiresAt,offlineLeaseExpiresAt,serverTimeUtc,validatedAt;factory AuthSession.fromJson(Map<String,dynamic>j)=>AuthSession(groupId:j['groupId'],userId:j['userId'],deviceId:j['deviceId'],name:j['name'],profile:j['profile'],isOwner:j['isOwner'],accessToken:j['accessToken'],accessTokenExpiresAt:DateTime.parse(j['accessTokenExpiresAt']),refreshToken:j['refreshToken'],refreshTokenExpiresAt:DateTime.parse(j['refreshTokenExpiresAt']),offlineLeaseExpiresAt:DateTime.parse(j['offlineLeaseExpiresAt']),serverTimeUtc:DateTime.parse(j['serverTimeUtc']),validatedAt:DateTime.parse(j['validatedAt']));}
