class ClientItem{const ClientItem({required this.id,required this.name,required this.phone});final String id,name,phone;factory ClientItem.fromJson(Map<String,dynamic>j)=>ClientItem(id:j['id'],name:j['name'],phone:j['phone']);}class ServiceItem{const ServiceItem({required this.id,required this.name,required this.price,required this.durationMinutes});final String id,name;final double price;final int durationMinutes;factory ServiceItem.fromJson(Map<String,dynamic>j)=>ServiceItem(id:j['id'],name:j['name'],price:(j['standardPrice']as num).toDouble(),durationMinutes:j['standardDurationMinutes']);}class AppointmentItem{const AppointmentItem({required this.id,required this.clientName,required this.startsAt,required this.endsAt,required this.status,required this.isFitIn});final String id,clientName,status;final DateTime startsAt,endsAt;final bool isFitIn;factory AppointmentItem.fromJson(Map<String,dynamic>j)=>AppointmentItem(id:j['id'],clientName:j['clientName'],startsAt:DateTime.parse(j['startsAt']),endsAt:DateTime.parse(j['endsAt']),status:j['status'],isFitIn:j['isFitIn']);}
class BckApiClient{BckApiClient({Dio?dio}):_dio=dio??Dio(BaseOptions(baseUrl:AppConfig.apiBaseUrl,connectTimeout:const Duration(seconds:10),receiveTimeout:const Duration(seconds:10),headers:const{'Accept':'application/json'}));final Dio _dio;String?_accessToken;void setAccessToken(String?token)=>_accessToken=token;Options get _authorizedOptions=>Options(headers:_accessToken==null?null:{'Authorization':'Bearer $_accessToken'});Future<ApiHealth>health()async=>ApiHealth.fromJson((await _dio.get<Map<String,dynamic>>('/api/v1/health')).data!);Future<BootstrapCompanyResponse>createCompany(BootstrapCompanyRequest r)async=>BootstrapCompanyResponse.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/bootstrap/company',data:r.toJson())).data!);Future<PairingResult>pairDevice({required String pairingCode,required String deviceId,required String deviceName,required String username,required String password})async=>PairingResult.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/devices/pair/consume',data:{'pairingCode':pairingCode,'deviceId':deviceId,'deviceName':deviceName,'platform':'ANDROID','username':username,'password':password})).data!);Future<AuthSession>login({required String groupId,required String username,required String password,required String deviceId})async{final s=AuthSession.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/auth/login',data:{'groupId':groupId,'username':username,'password':password,'deviceId':deviceId})).data!);setAccessToken(s.accessToken);return s;}Future<RefreshedTokens>refresh(String token)async{final r=RefreshedTokens.fromJson((await _dio.post<Map<String,dynamic>>('/api/v1/auth/refresh',data:{'refreshToken':token})).data!);setAccessToken(r.accessToken);return r;}Future<void>logout(String token)async{await _dio.post<void>('/api/v1/auth/logout',data:{'refreshToken':token});setAccessToken(null);}Future<Map<String,dynamic>>me()async=>(await _dio.get<Map<String,dynamic>>('/api/v1/auth/me',options:_authorizedOptions)).data!;Future<List<ClientItem>>clients(String groupId,{String query=''})async{final r=await _dio.get<List<dynamic>>('/api/v1/clients',queryParameters:{'q':query},options:_authorizedOptions);return r.data!.map((e)=>ClientItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<List<ServiceItem>>services(String groupId)async{final r=await _dio.get<List<dynamic>>('/api/v1/services',options:_authorizedOptions);return r.data!.map((e)=>ServiceItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<List<AppointmentItem>>appointments({required String groupId,required String professionalUserId,required DateTime from,required DateTime to})async{final r=await _dio.get<List<dynamic>>('/api/v1/appointments',queryParameters:{'professionalUserId':professionalUserId,'from':from.toUtc().toIso8601String(),'to':to.toUtc().toIso8601String()},options:_authorizedOptions);return r.data!.map((e)=>AppointmentItem.fromJson(Map<String,dynamic>.from(e))).toList();}Future<bool>availability({required String groupId,required String professionalUserId,required DateTime startsAt,required DateTime endsAt})async{final r=await _dio.get<Map<String,dynamic>>('/api/v1/appointments/availability',queryParameters:{'professionalUserId':professionalUserId,'startsAt':startsAt.toUtc().toIso8601String(),'endsAt':endsAt.toUtc().toIso8601String()},options:_authorizedOptions);return r.data!['available']as bool;}Future<AppointmentItem>createAppointment({required String groupId,required String professionalUserId,required String createdByUserId,String?clientId,String?walkInName,String?walkInPhone,required String serviceId,required DateTime startsAt,required int durationMinutes,bool isFitIn=false,bool forceConflict=false,String?notes})async{final r=await _dio.post<Map<String,dynamic>>('/api/v1/appointments',data:{'professionalUserId':professionalUserId,'clientId':clientId,'walkInName':walkInName,'walkInPhone':walkInPhone,'serviceId':serviceId,'startsAt':startsAt.toUtc().toIso8601String(),'durationMinutes':durationMinutes,'isFitIn':isFitIn,'forceConflict':forceConflict,'notes':notes},options:_authorizedOptions);return AppointmentItem.fromJson(r.data!);}}
